import{_ as t,o as s,c as a,a2 as r}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Supermarket","description":"","frontmatter":{},"headers":[],"relativePath":"guides/supermarket.md","filePath":"guides/supermarket.md","lastUpdated":1788855895000}'),i={name:"guides/supermarket.md"};function n(o,e,l,h,c,d){return s(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="supermarket" tabindex="-1">Supermarket <a class="header-anchor" href="#supermarket" aria-label="Permalink to &quot;Supermarket&quot;">​</a></h1><p>Supermarket is Memoh&#39;s built-in catalog for <strong>connectors</strong> and <strong>skills</strong>. Connectors bind third-party services such as GitHub or Notion to a bot; skills are reusable procedures the agent can load on demand.</p><p>The Web UI shows Supermarket under Settings with two tabs:</p><ul><li><strong>Connectors</strong></li><li><strong>Skills</strong></li></ul><p><strong>Connectors</strong> comes first and is the default landing tab when the server has <a href="/guides/connectors.html#requirements">Connect-It configured</a>. Without Connect-It, the tab is hidden and <strong>Skills</strong> is the default instead.</p><hr><h2 id="connect-a-service" tabindex="-1">Connect A Service <a class="header-anchor" href="#connect-a-service" aria-label="Permalink to &quot;Connect A Service&quot;">​</a></h2><p>The <strong>Connectors</strong> tab lists services a bot can connect through OAuth or an API key. Pick one, click <strong>Connect</strong>, select the target bot, and complete the authorization. The full flow — authentication methods, connection statuses, and how connector tools reach the bot — is documented in <a href="/guides/connectors.html">Connectors</a>.</p><hr><h2 id="install-a-skill" tabindex="-1">Install A Skill <a class="header-anchor" href="#install-a-skill" aria-label="Permalink to &quot;Install A Skill&quot;">​</a></h2><ol><li>Open <strong>Supermarket</strong> in the Web UI.</li><li>Switch to the <strong>Skills</strong> tab.</li><li>Choose a skill and click <strong>Install</strong>, or open the skill detail page and click <strong>Install to Bot</strong>.</li><li>Select the target bot.</li><li>Confirm the install.</li><li>The skill appears in that bot&#39;s <strong>Skills</strong> tab.</li></ol><p>Skills install into the bot&#39;s managed skills directory (<code>/data/skills/&lt;skill-name&gt;</code> inside the bot workspace). Skill detail pages show the author, version, registry, and links. See <a href="/guides/skills.html">Skills</a> for how skills are loaded and used.</p><hr><h2 id="configure-supermarket" tabindex="-1">Configure Supermarket <a class="header-anchor" href="#configure-supermarket" aria-label="Permalink to &quot;Configure Supermarket&quot;">​</a></h2><p>By default, Memoh reads Supermarket content from:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">supermarket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://supermarket.memoh.ai&quot;</span></span></code></pre></div><p>Operators can point <code>supermarket.base_url</code> at another trusted catalog. The configured endpoint is used for the connector list, skill lists, skill details, and skill downloads. The <strong>Registry</strong> filter in the Skills tab lets you narrow results to a single upstream registry.</p><hr><h2 id="contribute" tabindex="-1">Contribute <a class="header-anchor" href="#contribute" aria-label="Permalink to &quot;Contribute&quot;">​</a></h2><p>Contribute new skills here:</p><ul><li><a href="https://github.com/felinics/supermarket" target="_blank" rel="noreferrer">felinics/supermarket</a></li></ul>`,21)])])}const k=t(i,[["render",n]]);export{p as __pageData,k as default};
